          let bg0Cnt = GetGpuReg(REG_OFFSET_BG0CNT);
          let bg2Cnt = GetGpuReg(REG_OFFSET_BG2CNT);
          (bg0Cnt).priority = 0;
          (bg2Cnt).priority = 0;
          rt.SetGpuReg(REG_OFFSET_BG0CNT, bg0Cnt);
          rt.SetGpuReg(REG_OFFSET_BG2CNT, bg2Cnt);
