/** Source: contest.c → Task_UpdateAppealHearts */
export const Task_UpdateAppealHearts: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let contestant = task.data[3];
      let startHearts = task.data[0];
      let heartsDelta = task.data[1];

      if (++task.data[10] > 14)
      {
          let heartOffset = 0;
          let newNumHearts = 0;
          let pitchMod = 0;
          let onSecondLine = 0;

          task.data[10] = 0;
          if (task.data[1] == 0)
          {
               
              rt.DestroyTask(taskId);
              eContestGfxState[contestant].updatingAppealHearts = false;
              return;
          }
          else if (startHearts == 0)
          {
              if (heartsDelta < 0)
              {
                   
                  heartOffset = GetAppealHeartTileOffset(contestant) + 2;
                  task.data[1]++;
              }
              else
              {
                   
                  heartOffset = GetAppealHeartTileOffset(contestant);
                  task.data[1]--;
              }
              newNumHearts = task.data[0]++;
          }
          else
          {
              if (task.data[2] < 0)
              {
                   
                  if (heartsDelta < 0)
                  {
                       
                      newNumHearts = task.data[0]++;
                      task.data[1]++;
                      heartOffset = GetAppealHeartTileOffset(contestant) + 2;
                  }
                  else
                  {
                       
                      newNumHearts = --task.data[0];
                      heartOffset = 0;
                      task.data[1]--;
                  }
              }
              else
              {
                   
                  if (heartsDelta < 0)
                  {
                       
                      newNumHearts = --task.data[0];
                      heartOffset = 0;
                      task.data[1]++;
                  }
                  else
                  {
                       
                      newNumHearts = task.data[0]++;
                      task.data[1]--;
                      heartOffset = GetAppealHeartTileOffset(contestant);
                  }
              }
          }
          pitchMod = newNumHearts;
          onSecondLine = false;

           
          if (newNumHearts > 7)
          {
              onSecondLine = true;
              newNumHearts -= 8;
          }
          ContestBG_FillBoxWithTile(0, heartOffset, newNumHearts + 22, gContestantTurnOrder[contestant] * 5 + 2 + onSecondLine,  1, 1, 17);
          if (heartsDelta > 0)
          {
              PlaySE(SE_CONTEST_HEART);
              m4aMPlayImmInit(gMPlayInfo_SE1);
              m4aMPlayPitchControl(gMPlayInfo_SE1, TRACKS_ALL, pitchMod * 256);
          }
          else
          {
              PlaySE(SE_BOO);
          }

          if (!onSecondLine && newNumHearts == 0 && heartOffset == 0)
              task.data[2] = -task.data[2];
      }
};

