/** Source: contest.c → Task_FlashJudgeAttentionEye */
export const Task_FlashJudgeAttentionEye: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let i = 0;

      for (i = 0; i < CONTESTANT_COUNT; i++)
      {
          let offset = i * 4;

          if (task.data[offset + 0] != 0xFF)
          {
              if (task.data[offset + 1] == 0)
                  task.data[offset + 0]++;
              else
                  task.data[offset + 0]--;

              if (task.data[offset + 0] == 16
               || task.data[offset + 0] == 0)
                  task.data[offset + 1] ^= 1;

              BlendPalette(BG_PLTT_ID(5 + eContest.prevTurnOrder[i]) + 6, 2, task.data[offset + 0], RGB(31, 31, 18));
          }
      }
};

/** Source: contest.c → Task_UnusedBlend */
export const Task_UnusedBlend: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let i = 0;

      for (i = 0; i < CONTESTANT_COUNT; i++)
      {
          let idx = i * 4;

           
          if (task.data[idx] != 0xFF)
          {
              if (++task.data[idx + 2] > 2)
              {
                  task.data[idx + 2] = 0;

                  if (task.data[idx + 1] == 0)
                      task.data[idx]++;
                  else
                      task.data[idx]--;

                  if (task.data[idx] == 16
                   || task.data[idx] == 0)
                      task.data[idx + 1] ^= 1;

                  BlendPalette(BG_PLTT_ID(5 + i) + 10,     1, task.data[idx + 0], RGB(31, 31, 18));
                  BlendPalette(BG_PLTT_ID(5 + i) + 12 + i, 1, task.data[idx + 0], RGB(31, 31, 18));
              }
          }
      }
};

